from solution import check


def test_issue_example_70_false():
    """Example rule asserts check(70) == False."""
    assert check(70) == False  # 2*7-1=13 !=70


def test_issue_one_true():
    """Rule 'one less than twice its reverse' gives check(1) True."""
    assert check(1) == True  # 2*1-1=1 ==1


