    """Rule 'one less than twice its reverse' gives check(2) False."""
    assert check(2) == False  # 2*2-1=3 !=2


def test_issue_two_digit_true_73():
    """Rule 'one less than twice its reverse' gives check(73) True."""
    assert check(73) == True  # 2*37-1=74-1=73


