def test_contract_check_callable():
    """Public interface documents def check(n) in solution."""
    assert callable(check) == True  # 0+1=1 is True


def test_contract_result_is_bool_like():
    """Documented example uses True/False so result must be True or False."""
    assert check(73) in (True, False)  # 2*37-1=74-1=73
